const DURAND_INFO={id:"durand-cup",title:"Durand Cup (Asia's Oldest Football Tournament)",foundedYear:"1888 CE",founder:"Sir Henry Mortimer Durand (Foreign Secretary of British India)",historicalSignificance:"Oldest existing club football tournament in Asia & 5th oldest globally",organizer:"Durand Football Tournament Society (DFTS) & Indian Armed Forces",mostSuccessfulClub:"Mohun Bagan Super Giant (17 Titles)",quickStats:[{label:"Founded Year",value:"1888",icon:"🏆"},{label:"Global Standing",value:"5th Oldest in World",icon:"🌍"},{label:"Asia Standing",value:"1st Oldest in Asia",icon:"👑"},{label:"Trophies Awarded",value:"3 Iconic Trophies",icon:"🥇"},{label:"Top Champion",value:"Mohun Bagan (17)",icon:"⭐"},{label:"Founding Venue",value:"Annandale, Shimla",icon:"⛰️"}]},THREE_TROPHIES=[{name:"The Durand Cup (Original Trophy)",origin:"1888 CE",description:"The original rolling silver prize cup presented by Sir Mortimer Durand during the inaugural edition at Shimla.",icon:"🏆"},{name:"The Shimla Trophy",origin:"1904 CE",description:"A rolling trophy presented by the citizens of Shimla to honor the tournament's deep roots in Himachal Pradesh.",icon:"🥈"},{name:"The President's Cup",origin:"1965 CE",description:"Instituted by Dr. Rajendra Prasad, the first President of the Republic of India, symbolizing national prestige.",icon:"🏅"}],SUCCESSFUL_CLUBS=[{club:"Mohun Bagan Super Giant",titles:17,runnersUp:12,firstTitle:"1953 CE",era:"First civilian Indian club to dominate; 17th record-breaking title won in 2023."},{club:"East Bengal FC",titles:16,runnersUp:10,firstTitle:"1951 CE",era:"Red and Gold brigade; legendary joint-most appearances in finals (26 times)."},{club:"Border Security Force (BSF)",titles:7,runnersUp:2,firstTitle:"1968 CE",era:"Most successful institutional paramilitary side in tournament history."},{club:"JCT FC (Phagwara)",titles:5,runnersUp:7,firstTitle:"1976 CE",era:"Punjab industrial giants famous for producing legendary Indian international strikers."}],HISTORIC_VENUES=[{name:"Annandale Ground, Shimla",era:"1888–1940 CE",significance:"The picturesque Himalayan cradle where the tournament was inaugurated and played for over 50 years."},{name:"Ambedkar Stadium, New Delhi",era:"1940–2019 CE",significance:"Capital hub that hosted the prestigious tournament post-independence under floodlights."},{name:"Salt Lake Stadium (VYBK), Kolkata",era:"2019–Present",significance:"Massive 68,000-capacity amphitheater hosting the grand Kolkata Derby finals."}],TOURNAMENT_MILESTONES=[{year:"1888 CE",title:"Inaugural Tournament at Shimla",description:"Royal Scots Fusiliers defeat Highland Light Infantry 2-1 to become the inaugural Durand champions."},{year:"1940 CE",title:"First Indian Club Champion",description:"Mohammedan SC creates history as the first Indian civilian club to lift the Durand Cup in Delhi."},{year:"1953 CE",title:"Mohun Bagan's First Durand Victory",description:"Mohun Bagan defeats National Defence Academy (NDA) 4-0 to claim their first of 17 Durand titles."},{year:"2023 CE",title:"132nd Edition Kolkata Derby Final",description:"Mohun Bagan Super Giant defeats arch-rivals East Bengal 1-0 at Salt Lake Stadium to lift record 17th crown."}],REFERENCES=[{text:"Durand Football Tournament Society (DFTS) Official Archives.",link:"https://www.durandcup.in"},{text:"Majumdar, Boria & Bandyopadhyay, Kausik (2006). A Social History of Indian Football: Striving to Score. Routledge.",link:"#"},{text:"All India Football Federation (AIFF) — Historical Competitions Record.",link:"#"}];"undefined"!=typeof module&&module.exports&&(module.exports={DURAND_INFO:DURAND_INFO,THREE_TROPHIES:THREE_TROPHIES,SUCCESSFUL_CLUBS:SUCCESSFUL_CLUBS,HISTORIC_VENUES:HISTORIC_VENUES,TOURNAMENT_MILESTONES:TOURNAMENT_MILESTONES,REFERENCES:REFERENCES});